    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(this));
    }

    function _run(uint256 _unlockTime) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        bool reverted;
        try c.Put{value: 0}(_unlockTime) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(uint256 _unlockTime) public {
        _run(_unlockTime);
    }

